+ '<span class="kw">import</span> torch\n'
+ '<span class="kw">from</span> torch.quantization <span class="kw">import</span> quantize_dynamic\n\n'
+ 'model_fp32 = AutoModelForSequenceClassification.<span class="fn">from_pretrained</span>(model_path)\n\n'
+ 'model_int8 = <span class="fn">quantize_dynamic</span>(\n'
+ '    model_fp32,\n'
+ '    {torch.nn.Linear},               <span class="cm"># quantize Linear layers only (positional arg)</span>\n'
+ '    dtype=torch.qint8\n'
+ ')\n\n'
+ '<span class="cm"># Compare sizes</span>\n'
+ '<span class="kw">import</span> os\n'
+ 'torch.<span class="fn">save</span>(model_fp32.<span class="fn">state_dict</span>(), <span class="str">"/tmp/bert_fp32.pt"</span>)\n'
+ 'torch.<span class="fn">save</span>(model_int8.<span class="fn">state_dict</span>(), <span class="str">"/tmp/bert_int8.pt"</span>)\n\n'
+ 'fp32_mb = os.path.<span class="fn">getsize</span>(<span class="str">"/tmp/bert_fp32.pt"</span>) / <span class="num">1e6</span>\n'
